  passwordResets discussion_board_member_password_resets[]
  emailVerifications discussion_board_member_email_verifications[]
  auditLogs discussion_board_audit_logs[]
  articles discussion_board_articles[]
  comments discussion_board_comments[]
  adminRequests discussion_board_admin_requests[]
  banRecords discussion_board_ban_records[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([ban_status])
}

