  discussionBoardMember discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  discussionBoardAdmin  discussion_board_admins  @relation(fields: [discussion_board_admin_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, unbanned_at], map: "discussion_board_ban_records_discussion_board_member_i_b6c5070e")
