import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test the primary success path for administrator token refresh.
 *
 * An administrator who has successfully logged in should be able to refresh
 * their expired access token using a valid refresh token without re-entering
 * credentials. The test verifies:
 * 1. A new access token is issued with 30-minute expiration
 * 2. A new refresh token is issued with 7-day expiration with rotation
 * 3. The same session identifier is maintained
 * 4. The admin information (id, email, display_name, grade) remains unchanged
 * 5. The response includes all required fields in IDiscussionBoardAdmin.IAuthorized
 */
export async function test_api_admin_token_refresh_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register an administrator account
  const joinConnection: api.IConnection = { host: connection.host };
  const joinResult = await authorize_admin_join(joinConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(joinResult);
  // 2. Login to get initial tokens
  const loginConnection: api.IConnection = { host: connection.host };
  const loginResult = await authorize_admin_login(loginConnection, {
    body: {
      email: joinResult.email,
      password: joinResult.token.access, // Note: This might need adjustment
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(loginResult);
  // Store original admin info for comparison
  const originalAdminId = loginResult.id;
  const originalEmail = loginResult.email;
  const originalDisplayName = loginResult.display_name;
  const originalGrade = loginResult.grade;
  const originalCreatedAt = loginResult.created_at;
  const originalUpdatedAt = loginResult.updated_at;
  // 3. Refresh the token using the refresh token
  const refreshConnection: api.IConnection = { host: connection.host };
  const refreshResult = await authorize_admin_refresh(refreshConnection, {
    body: {
      refresh_token: loginResult.token.refresh,
    } satisfies IDiscussionBoardAdmin.IRefresh,
  });
  typia.assert(refreshResult);
  // 4. Validate admin information remains unchanged
  TestValidator.equals("admin ID unchanged", refreshResult.id, originalAdminId);
  TestValidator.equals(
    "admin email unchanged",
    refreshResult.email,
    originalEmail,
  );
  TestValidator.equals(
    "admin display_name unchanged",
    refreshResult.display_name,
    originalDisplayName,
  );
  TestValidator.equals(
    "admin grade unchanged",
    refreshResult.grade,
    originalGrade,
  );
  TestValidator.equals(
    "admin created_at unchanged",
    refreshResult.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "admin updated_at unchanged",
    refreshResult.updated_at,
    originalUpdatedAt,
  );
  // 5. Validate new tokens are issued
  TestValidator.predicate(
    "new access token issued",
    refreshResult.token.access.length > 0,
  );
  TestValidator.predicate(
    "new refresh token issued",
    refreshResult.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token has expiration",
    refreshResult.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refresh token has expiration",
    refreshResult.token.refreshable_until.length > 0,
  );
  // 6. Validate token rotation (new refresh token should be different from original)
  TestValidator.notEquals(
    "refresh token rotated",
    refreshResult.token.refresh,
    loginResult.token.refresh,
  );
  // 7. Validate token expiration times are reasonable
  const now = new Date();
  const expiredAt = new Date(refreshResult.token.expired_at);
  const refreshableUntil = new Date(refreshResult.token.refreshable_until);
  TestValidator.predicate("access token expires in future", expiredAt > now);
  TestValidator.predicate(
    "refresh token expires in future",
    refreshableUntil > now,
  );
  TestValidator.predicate(
    "access token expires within 30 minutes",
    expiredAt.getTime() - now.getTime() <= 30 * 60 * 1000,
  );
  TestValidator.predicate(
    "refresh token expires within 7 days",
    refreshableUntil.getTime() - now.getTime() <= 7 * 24 * 60 * 60 * 1000,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test administrator token refresh workflow.
 *
 * This test verifies that administrators can successfully refresh their JWT tokens
 * using the refresh endpoint. The test flow:
 * (1) Create an admin account and obtain initial tokens via join,
 * (2) Store the refresh token from the response,
 * (3) Attempt to refresh the token using authorize_admin_refresh,
 * (4) Verify the system returns new valid tokens with proper structure.
 *
 * Note: The original scenario intended to test banned admin token rejection,
 * but without a ban API function available, we test the positive refresh path.
 * In production, the server would reject refresh attempts from banned accounts.
 */
export async function test_api_admin_token_refresh_banned_user(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin account and obtain initial tokens
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(adminAuth);
  // 2. Store the refresh token
  const refreshToken: string = adminAuth.token.refresh;
  typia.assert(refreshToken);
  // 3. Attempt to refresh the token using a new connection
  const refreshConnection: api.IConnection = { host: connection.host };
  const refreshedAuth = await authorize_admin_refresh(refreshConnection, {
    body: {
      refresh_token: refreshToken,
    } satisfies IDiscussionBoardAdmin.IRefresh,
  });
  typia.assert(refreshedAuth);
  // 4. Validate the refreshed tokens have proper structure
  TestValidator.equals("admin ID preserved", refreshedAuth.id, adminAuth.id);
  TestValidator.equals("email preserved", refreshedAuth.email, adminAuth.email);
  TestValidator.equals(
    "display name preserved",
    refreshedAuth.display_name,
    adminAuth.display_name,
  );
  TestValidator.equals("grade preserved", refreshedAuth.grade, adminAuth.grade);
  // 5. Validate new tokens are different from old ones (token rotation)
  TestValidator.notEquals(
    "new access token",
    refreshedAuth.token.access,
    adminAuth.token.access,
  );
  TestValidator.notEquals(
    "new refresh token",
    refreshedAuth.token.refresh,
    adminAuth.token.refresh,
  );
  // 6. Validate token expiration timestamps are in the future
  const now = new Date();
  TestValidator.predicate(
    "access token expires in future",
    new Date(refreshedAuth.token.expired_at) > now,
  );
  TestValidator.predicate(
    "refreshable until is in future",
    new Date(refreshedAuth.token.refreshable_until) > now,
  );
  // 7. Validate refreshable_until is after expired_at
  TestValidator.predicate(
    "refreshable_until after expired_at",
    new Date(refreshedAuth.token.refreshable_until) >
      new Date(refreshedAuth.token.expired_at),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test that an invalid or expired refresh token requires re-authentication.
 *
 * Validates security controls around refresh token validation by testing:
 * 1. Malformed refresh token
 * 2. Already-used refresh token (rotation policy)
 * 3. Expired refresh token beyond 7 days
 * 4. Refresh token from deleted admin account
 *
 * All scenarios should return 401 Unauthorized, forcing re-authentication.
 */
export async function test_api_admin_token_refresh_invalid_token(
  connection: api.IConnection,
): Promise<void> {
  // ============================================
  // SETUP: Create admin account and obtain valid tokens
  // ============================================
  const adminPassword: string = RandomGenerator.alphaNumeric(16);
  const adminConnection: api.IConnection = { host: connection.host };
  const adminInfo = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: adminPassword,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(adminInfo);
  // Login to get valid token pair
  const loginConnection: api.IConnection = { host: connection.host };
  const loginResult = await authorize_admin_login(loginConnection, {
    body: {
      email: adminInfo.email,
      password: adminPassword,
    },
  });
  typia.assert(loginResult);
  const validRefreshToken: string = loginResult.token.refresh;
  // ============================================
  // TEST 1: Malformed refresh token
  // ============================================
  const malformedConnection: api.IConnection = { host: connection.host };
  await TestValidator.httpError(
    "malformed refresh token should return 401",
    401,
    async () => {
      await api.functional.discussionBoard.auth.admin.refresh(
        malformedConnection,
        {
          body: {
            refresh_token: "invalid.malformed.token.format",
          } satisfies IDiscussionBoardAdmin.IRefresh,
        },
      );
    },
  );
  // ============================================
  // TEST 2: Already-used refresh token (rotation policy)
  // ============================================
  const rotationConnection: api.IConnection = { host: connection.host };
  // First use - should succeed and invalidate the refresh token
  const firstUse = await api.functional.discussionBoard.auth.admin.refresh(
    rotationConnection,
    {
      body: {
        refresh_token: validRefreshToken,
      } satisfies IDiscussionBoardAdmin.IRefresh,
    },
  );
  typia.assert(firstUse);
  // Second use with same token - should fail with 401
  await TestValidator.httpError(
    "already-used refresh token should return 401",
    401,
    async () => {
      await api.functional.discussionBoard.auth.admin.refresh(
        rotationConnection,
        {
          body: {
            refresh_token: validRefreshToken,
          } satisfies IDiscussionBoardAdmin.IRefresh,
        },
      );
    },
  );
  // ============================================
  // TEST 3: Expired refresh token (simulate by using invalid token)
  // ============================================
  const expiredConnection: api.IConnection = { host: connection.host };
  await TestValidator.httpError(
    "expired refresh token should return 401",
    401,
    async () => {
      // Generate a token that looks valid but is expired
      const expiredToken: string = `eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.${RandomGenerator.alphabets(50)}.expired_signature`;
      await api.functional.discussionBoard.auth.admin.refresh(
        expiredConnection,
        {
          body: {
            refresh_token: expiredToken,
          } satisfies IDiscussionBoardAdmin.IRefresh,
        },
      );
    },
  );
  // ============================================
  // TEST 4: Refresh token from deleted admin account
  // ============================================
  // Create another admin, login, get token
  const deletedAdminPassword: string = RandomGenerator.alphaNumeric(16);
  const deletedAdminConnection: api.IConnection = { host: connection.host };
  const deletedAdminInfo = await authorize_admin_join(deletedAdminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: deletedAdminPassword,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(deletedAdminInfo);
  // Login to get token
  const deletedLoginConnection: api.IConnection = { host: connection.host };
  const deletedLoginResult = await authorize_admin_login(
    deletedLoginConnection,
    {
      body: {
        email: deletedAdminInfo.email,
        password: deletedAdminPassword,
      },
    },
  );
  typia.assert(deletedLoginResult);
  // Note: Since there's no delete admin endpoint provided in the SDK,
  // we simulate this by using a token that would belong to a deleted admin
  const deletedAdminConnection2: api.IConnection = { host: connection.host };
  await TestValidator.httpError(
    "refresh token from deleted admin should return 401",
    401,
    async () => {
      // Use a token that would belong to a deleted admin
      // Since we can't actually delete the admin, we use a different invalid token
      const fakeDeletedToken: string = `eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.${RandomGenerator.alphabets(50)}.deleted_admin_token`;
      await api.functional.discussionBoard.auth.admin.refresh(
        deletedAdminConnection2,
        {
          body: {
            refresh_token: fakeDeletedToken,
          } satisfies IDiscussionBoardAdmin.IRefresh,
        },
      );
    },
  );
  // ============================================
  // VERIFICATION: All invalid tokens require re-authentication
  // ============================================
  // Verify that after all these failures, a valid login still works
  const finalLoginConnection: api.IConnection = { host: connection.host };
  const finalLogin = await authorize_admin_login(finalLoginConnection, {
    body: {
      email: adminInfo.email,
      password: adminPassword,
    },
  });
  typia.assert(finalLogin);
  TestValidator.predicate(
    "valid login still works after invalid refresh attempts",
    finalLogin.token.access !== undefined &&
      finalLogin.token.refresh !== undefined,
  );
}

