export async function test_api_article_update_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member joins the system
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(memberAuth);
  // 2. Create an article with initial tags
  // Note: Using generated UUID for section_id - assumes test environment has sections
  const initialTags = [
    RandomGenerator.name(1),
    RandomGenerator.name(1),
    RandomGenerator.name(1),
  ];
  const article = await generate_random_discussion_board_member_articles_create(
    memberConnection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        discussion_board_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        tags: initialTags,
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);
  // 3. Store original timestamps for validation
  const originalCreatedAt = article.created_at;
  const originalUpdatedAt = article.updated_at;
  // 4. Update the article with new title, body, and tags
  const updatedTags = [RandomGenerator.name(1), RandomGenerator.name(1)];
  const updatedArticle =
    await api.functional.discussionBoard.member.articles.update(
      memberConnection,
      {
        articleId: article.id,
        body: {
          title: RandomGenerator.paragraph({ sentences: 2 }),
          body: RandomGenerator.content({ paragraphs: 4 }),
          tags: updatedTags,
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(updatedArticle);
  // 5. Validate the update results
  // Verify title was updated
  TestValidator.notEquals(
    "title should be updated",
    article.title,
    updatedArticle.title,
  );
  // Verify body was updated
  TestValidator.notEquals(
    "body should be updated",
    article.body,
    updatedArticle.body,
  );
  // Verify tags were replaced (not just added)
