    article.created_at,
    updatedArticle.created_at,
  );
  // Verify updated_at was changed
  TestValidator.notEquals(
    "updated_at should be updated",
    article.updated_at,
    updatedArticle.updated_at,
  );
  // Verify author information is preserved
  TestValidator.equals(
    "author id should match",
    article.author.id,
    updatedArticle.author.id,
  );
  // Verify section is preserved
  TestValidator.equals(
    "section id should match",
    article.section.id,
    updatedArticle.section.id,
  );
}

