export async function test_api_article_update_tag_replacement(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member joins and authenticates
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(memberAuth);
  // 2. Create initial tags for the article (3 tags)
  const initialTags = ArrayUtil.repeat(3, () => RandomGenerator.name(1));
  // 3. Create article with initial tags
  const article = await api.functional.discussionBoard.member.articles.create(
    memberConnection,
    {
      body: {
        title: RandomGenerator.name(3),
        body: RandomGenerator.content({ paragraphs: 2 }),
        discussion_board_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        tags: initialTags,
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);
  // 4. Verify article has exactly 3 initial tags
  TestValidator.equals("initial tag count", article.tags.length, 3);
  // 5. Store initial tag names for later verification
  const initialTagNames = article.tags.map((tag) => tag.name);
  // 6. Update article with completely different tags (2 new tags)
  const newTags = ArrayUtil.repeat(2, () => RandomGenerator.name(1));
  // Ensure new tags are different from initial tags
  const distinctNewTags = newTags.filter(
    (newTag) => !initialTagNames.includes(newTag),
  );
  const updatedArticle =
    await api.functional.discussionBoard.member.articles.update(
      memberConnection,
      {
        articleId: article.id,
        body: {
          tags: distinctNewTags,
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(updatedArticle);
  // 7. Verify article now has exactly 2 tags (not 5)
  TestValidator.equals("updated tag count", updatedArticle.tags.length, 2);
  // 8. Verify new tags are present
  const updatedTagNames = updatedArticle.tags.map((tag) => tag.name);
  TestValidator.predicate("all new tags present", () =>
    distinctNewTags.every((tag) => updatedTagNames.includes(tag)),
  );
  // 9. Verify old tags are NOT associated with this article
  TestValidator.predicate("old tags removed", () =>
    initialTagNames.every((tag) => !updatedTagNames.includes(tag)),
  );
}

