  TestValidator.equals(
    "pagination.page=2",
    snapshotsPage2.pagination.current,
    2,
  );
  TestValidator.equals(
    "pagination.limit=10",
    snapshotsPage2.pagination.limit,
    10,
  );
  // 10. Test sorting descending (default)
