export async function test_api_system_setting_deletion_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(admin);
  // 2. Generate a non-existent setting key
  const nonExistentKey: string = `non_existent_setting_${typia.random<string & tags.Format<"uuid">>()}`;
  // 3. Attempt to delete the non-existent setting and verify 404 error
  await TestValidator.httpError(
    "deleting non-existent setting returns 404",
    404,
    async () => {
      await api.functional.discussionBoard.admin.system.settings.erase(
        adminConnection,
        {
          settingKey: nonExistentKey,
        },
      );
    },
  );
}

