/**
 * Test article search with empty results handling.
 *
 * 1. Create guest session for authentication
 * 2. Search with unique keyword that doesn't exist in any article
 * 3. Verify empty data array response
 * 4. Verify pagination metadata shows 0 records and 0 pages
 * 5. Test with non-existent tag filters
 * 6. Verify search query preserved in context
 */
export async function test_api_article_search_empty_results_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create guest session for authentication
  const guestConnection: api.IConnection = { host: connection.host };
  const guestAuth = await authorize_guest_join(guestConnection, {
    body: {
      device_fingerprint: RandomGenerator.alphaNumeric(32),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardGuest.IJoin,
  });
  typia.assert(guestAuth);
  // 2. Search with unique keyword that doesn't exist in any article
  const uniqueKeyword = `zqx_${RandomGenerator.alphaNumeric(16)}_nonexistent`;
  const searchResult =
    await api.functional.discussionBoard.guest.articles.search(
      guestConnection,
      {
        body: {
          search: uniqueKeyword,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardArticle.IRequest,
      },
    );
  typia.assert(searchResult);
  // 3. Verify empty data array
  TestValidator.equals("data array is empty", searchResult.data.length, 0);
  // 4. Verify pagination metadata shows 0 records and 0 pages
  TestValidator.equals("current page is 1", searchResult.pagination.current, 1);
  TestValidator.equals("limit is 20", searchResult.pagination.limit, 20);
  TestValidator.equals(
    "total records is 0",
    searchResult.pagination.records,
    0,
  );
  TestValidator.equals("total pages is 0", searchResult.pagination.pages, 0);
