    firstRejection.status,
    "rejected",
  );
  TestValidator.predicate(
    "reviewed_at is set",
    firstRejection.reviewed_at !== null,
  );
  TestValidator.predicate("reviewer is set", firstRejection.reviewer !== null);
}

