        id: decoded.id,
        session_id: decoded.session_id,
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires) as string &
      tags.Format<"date-time">,
    refreshable_until: toISOStringSafe(refreshExpires) as string &
      tags.Format<"date-time">,
  };
  // 8. Update session expiration
  await MyGlobal.prisma.discussion_board_member_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpires },
  });
  // 9. Return member profile with new tokens
  return {
    id: member.id,
    email: member.email,
    displayName: member.display_name,
    bio: member.bio ?? undefined,
    banStatus: member.ban_status,
    banReason: member.ban_reason ?? undefined,
    createdAt: toISOStringSafe(member.created_at) as string &
      tags.Format<"date-time">,
    updatedAt: toISOStringSafe(member.updated_at) as string &
      tags.Format<"date-time">,
    deletedAt: null,
    token,
  } satisfies IDiscussionBoardMember.IAuthorized;
}

import { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchDiscussionBoardAdminReportsContent(props: {
  admin: AdminPayload;
  body: IDiscussionBoardContentReport.IRequest;
}): Promise<IPageIDiscussionBoardContentReport.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  // Parse date filters
  const dateFrom = props.body.date_from ? new Date(props.body.date_from) : null;
  const dateTo = props.body.date_to ? new Date(props.body.date_to) : null;
  // Build where conditions for articles
  const articleWhere: Prisma.discussion_board_articlesWhereInput = {
    deleted_at: null,
  };
  if (dateFrom || dateTo) {
    const created_at: Prisma.DateTimeFilter = {};
    if (dateFrom) {
      created_at.gte = dateFrom;
    }
    if (dateTo) {
      created_at.lte = dateTo;
    }
    articleWhere.created_at = created_at;
  }
  if (props.body.section_id) {
    articleWhere.discussion_board_section_id = props.body.section_id;
  }
  // Build where conditions for comments
  const commentWhere: Prisma.discussion_board_commentsWhereInput = {};
  if (dateFrom || dateTo) {
    const created_at: Prisma.DateTimeFilter = {};
    if (dateFrom) {
      created_at.gte = dateFrom;
    }
    if (dateTo) {
      created_at.lte = dateTo;
    }
    commentWhere.created_at = created_at;
  }
  if (props.body.section_id) {
    commentWhere.article = {
      discussion_board_section_id: props.body.section_id,
    };
  }
  // Filter by content type
  if (props.body.content_type === "articles") {
    // Only count articles - comments will be 0
  } else if (props.body.content_type === "comments") {
    // Only count comments - articles will be 0
    articleWhere.id = { in: [] };
  }
  // Get total articles
  const totalArticles = await MyGlobal.prisma.discussion_board_articles.count({
    where: articleWhere,
  });
  // Get total comments
  const totalComments =
    props.body.content_type === "articles"
      ? 0
      : await MyGlobal.prisma.discussion_board_comments.count({
          where: commentWhere,
        });
  // Get active sections count
  const activeSectionsData =
    await MyGlobal.prisma.discussion_board_articles.groupBy({
      by: ["discussion_board_section_id"],
      where: {
        ...articleWhere,
        deleted_at: null,
      },
      _count: { id: true },
    });
  const activeSectionsCount = activeSectionsData.length;
  // Get total sections
  const totalSections = await MyGlobal.prisma.discussion_board_sections.count({
    where: { deleted_at: null },
  });
  // Get unique authors
  const uniqueAuthorsData =
    await MyGlobal.prisma.discussion_board_articles.groupBy({
      by: ["discussion_board_member_id"],
      where: {
        ...articleWhere,
        deleted_at: null,
      },
      _count: { id: true },
    });
  const uniqueAuthors = uniqueAuthorsData.length;
  // Calculate average articles per section
  const averageArticlesPerSection =
    activeSectionsCount > 0 ? totalArticles / activeSectionsCount : 0;
  // Get section breakdown
  const sectionBreakdownData =
    await MyGlobal.prisma.discussion_board_articles.groupBy({
      by: ["discussion_board_section_id"],
      where: {
        ...articleWhere,
        deleted_at: null,
      },
      _count: { id: true },
    });
  const sectionIds = sectionBreakdownData.map(
    (d) => d.discussion_board_section_id,
  );
  const sections = await MyGlobal.prisma.discussion_board_sections.findMany({
    where: { id: { in: sectionIds }, deleted_at: null },
    select: { id: true, name: true },
  });
  const sectionMap = new Map(sections.map((s) => [s.id, s.name]));
  const sectionBreakdown: IDiscussionBoardContentReport.ISectionBreakdown[] =
    sectionBreakdownData.map((d) => ({
      section_id: d.discussion_board_section_id as string & tags.Format<"uuid">,
      section_name: sectionMap.get(d.discussion_board_section_id) ?? "Unknown",
      article_count: d._count.id,
    }));
  // Get tag statistics
  const articleIds = await MyGlobal.prisma.discussion_board_articles.findMany({
    where: articleWhere,
    select: { id: true },
  });
  const articleIdSet = new Set(articleIds.map((a) => a.id));
  const tagUsageData =
    await MyGlobal.prisma.discussion_board_article_tags.groupBy({
      by: ["discussion_board_tag_id"],
      where: {
        discussion_board_article_id: { in: Array.from(articleIdSet) },
      },
      _count: { id: true },
    });
  const tagIds = tagUsageData.map((d) => d.discussion_board_tag_id);
  const tagList = await MyGlobal.prisma.discussion_board_tags.findMany({
    where: { id: { in: tagIds }, deleted_at: null },
    select: { id: true, name: true },
  });
  const tagMap = new Map(tagList.map((t) => [t.id, t.name]));
  const tagStatistics: IDiscussionBoardContentReport.ITagUsage[] =
    tagUsageData.map((d) => ({
      tag_id: d.discussion_board_tag_id as string & tags.Format<"uuid">,
      tag_name: tagMap.get(d.discussion_board_tag_id) ?? "Unknown",
      usage_count: d._count.id,
    }));
  // Calculate engagement trend
  let engagementTrend: "increasing" | "stable" | "decreasing" = "stable";
  if (dateFrom && dateTo) {
    const duration = dateTo.getTime() - dateFrom.getTime();
    const prevPeriodStart = new Date(dateFrom.getTime() - duration);
    const prevPeriodEnd = dateFrom;
    const prevArticleWhere: Prisma.discussion_board_articlesWhereInput = {
      created_at: { gte: prevPeriodStart, lt: prevPeriodEnd },
      deleted_at: null,
    };
    if (props.body.section_id) {
      prevArticleWhere.discussion_board_section_id = props.body.section_id;
    }
    const prevCount = await MyGlobal.prisma.discussion_board_articles.count({
      where: prevArticleWhere,
    });
    if (prevCount > 0) {
      if (totalArticles > prevCount * 1.1) {
        engagementTrend = "increasing";
      } else if (totalArticles < prevCount * 0.9) {
        engagementTrend = "decreasing";
      }
    }
  }
  // Get peak activity date
  let peakActivityDate: (string & tags.Format<"date">) | null = null;
  if (totalArticles > 0 && dateFrom && dateTo) {
    const dailyCounts = await MyGlobal.prisma.$queryRaw<
      Array<{
        date: string;
        count: number;
      }>
    >`
      SELECT DATE(created_at) as date, COUNT(*) as count
      FROM discussion_board_articles
      WHERE created_at >= ${dateFrom}
        AND created_at <= ${dateTo}
        AND deleted_at IS NULL
      GROUP BY DATE(created_at)
      ORDER BY count DESC
      LIMIT 1
    `;
    if (dailyCounts[0]?.date) {
      peakActivityDate = dailyCounts[0].date as string & tags.Format<"date">;
    }
  }
  // Create report record
  const report: IDiscussionBoardContentReport.ISummary = {
    id: v4() as string & tags.Format<"uuid">,
    period_start: (props.body.date_from ??
      toISOStringSafe(new Date())) as string & tags.Format<"date-time">,
    period_end: (props.body.date_to ?? toISOStringSafe(new Date())) as string &
      tags.Format<"date-time">,
    total_articles: totalArticles,
    total_comments: totalComments,
    active_sections_count: activeSectionsCount,
    total_sections: totalSections,
    unique_authors: uniqueAuthors,
    average_articles_per_section: averageArticlesPerSection,
    section_breakdown: sectionBreakdown,
    tag_statistics: tagStatistics,
    engagement_trend: engagementTrend,
    peak_activity_date: peakActivityDate,
    created_at: toISOStringSafe(new Date()) as string &
      tags.Format<"date-time">,
  };
  // Pagination - single report
  const total = 1;
  const totalPages = Math.ceil(total / limit);
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: totalPages,
    } satisfies IPage.IPagination,
    data: page <= totalPages ? [report] : [],
  } satisfies IPageIDiscussionBoardContentReport.ISummary;
}

import { IDiscussionBoardGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestSession";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIDiscussionBoardGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuestSession";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { DiscussionBoardAdminAtSummaryTransformer } from "../transformers/DiscussionBoardAdminAtSummaryTransformer";
import { DiscussionBoardGuestAtSummaryTransformer } from "../transformers/DiscussionBoardGuestAtSummaryTransformer";
import { DiscussionBoardMemberAtSummaryTransformer } from "../transformers/DiscussionBoardMemberAtSummaryTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchDiscussionBoardMemberSessions(props: {
  member: MemberPayload;
  body: IDiscussionBoardGuestSession.IRequest;
}): Promise<IPageIDiscussionBoardGuestSession.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  // Determine which session types to query
  const queryMember =
    props.body.session_type === undefined ||
    props.body.session_type === "member";
  const queryAdmin =
    props.body.session_type === undefined ||
    props.body.session_type === "admin";
  const queryGuest =
    props.body.session_type === undefined ||
    props.body.session_type === "guest";
  // Build common WHERE conditions
  const buildMemberWhere = ():
    | Prisma.discussion_board_member_sessionsWhereInput
    | undefined => {
    const conditions: Prisma.discussion_board_member_sessionsWhereInput[] = [];
    if (props.body.member_id) {
      conditions.push({ discussion_board_member_id: props.body.member_id });
    }
    if (props.body.ip) {
      conditions.push({ ip: props.body.ip });
    }
    if (props.body.created_at_from || props.body.created_at_to) {
      const dateRange: Prisma.DateTimeFilter = {};
      if (props.body.created_at_from) {
        dateRange.gte = new Date(props.body.created_at_from);
      }
      if (props.body.created_at_to) {
        dateRange.lte = new Date(props.body.created_at_to);
      }
      conditions.push({ created_at: dateRange });
    }
    if (props.body.expired !== undefined) {
      const now = new Date();
      if (props.body.expired) {
        conditions.push({ expired_at: { lt: now } });
      } else {
        conditions.push({ expired_at: { gte: now } });
      }
    }
    return conditions.length > 0 ? { AND: conditions } : undefined;
  };
  const buildAdminWhere = ():
    | Prisma.discussion_board_admin_sessionsWhereInput
    | undefined => {
    const conditions: Prisma.discussion_board_admin_sessionsWhereInput[] = [];
    if (props.body.admin_id) {
      conditions.push({ discussion_board_admin_id: props.body.admin_id });
    }
    if (props.body.ip) {
      conditions.push({ ip: props.body.ip });
    }
    if (props.body.created_at_from || props.body.created_at_to) {
      const dateRange: Prisma.DateTimeFilter = {};
      if (props.body.created_at_from) {
        dateRange.gte = new Date(props.body.created_at_from);
      }
      if (props.body.created_at_to) {
        dateRange.lte = new Date(props.body.created_at_to);
      }
      conditions.push({ created_at: dateRange });
    }
    if (props.body.expired !== undefined) {
      const now = new Date();
      if (props.body.expired) {
        conditions.push({ expired_at: { lt: now } });
      } else {
        conditions.push({ expired_at: { gte: now } });
      }
    }
    return conditions.length > 0 ? { AND: conditions } : undefined;
  };
  const buildGuestWhere = ():
    | Prisma.discussion_board_guest_sessionsWhereInput
    | undefined => {
    const conditions: Prisma.discussion_board_guest_sessionsWhereInput[] = [];
    if (props.body.guest_id) {
      conditions.push({ discussion_board_guest_id: props.body.guest_id });
    }
    if (props.body.ip) {
      conditions.push({ ip: props.body.ip });
    }
    if (props.body.created_at_from || props.body.created_at_to) {
      const dateRange: Prisma.DateTimeFilter = {};
      if (props.body.created_at_from) {
        dateRange.gte = new Date(props.body.created_at_from);
      }
      if (props.body.created_at_to) {
        dateRange.lte = new Date(props.body.created_at_to);
      }
      conditions.push({ created_at: dateRange });
    }
    if (props.body.expired !== undefined) {
      const now = new Date();
      if (props.body.expired) {
        conditions.push({ expired_at: { lt: now } });
      } else {
        conditions.push({ expired_at: { gte: now } });
      }
    }
    return conditions.length > 0 ? { AND: conditions } : undefined;
  };
  // Determine sort order
  const orderByField = props.body.sort_by ?? "created_at";
  const sortOrder = props.body.order ?? "desc";
  const orderByInput = { [orderByField]: sortOrder };
  // Query member sessions
  const memberSessions = queryMember
    ? await MyGlobal.prisma.discussion_board_member_sessions.findMany({
        where: buildMemberWhere(),
        skip,
        take: limit,
        orderBy: orderByInput,
        include: {
          member: {
            select: DiscussionBoardMemberAtSummaryTransformer.select().select,
          },
        },
      })
    : [];
  // Query admin sessions
  const adminSessions = queryAdmin
    ? await MyGlobal.prisma.discussion_board_admin_sessions.findMany({
        where: buildAdminWhere(),
        skip,
        take: limit,
        orderBy: orderByInput,
        include: {
          discussionBoardAdmin: {
            select: DiscussionBoardAdminAtSummaryTransformer.select().select,
          },
        },
      })
    : [];
  // Query guest sessions
  const guestSessions = queryGuest
    ? await MyGlobal.prisma.discussion_board_guest_sessions.findMany({
        where: buildGuestWhere(),
        skip,
        take: limit,
        orderBy: orderByInput,
        include: {
          guest: {
            select: DiscussionBoardGuestAtSummaryTransformer.select().select,
          },
        },
      })
    : [];
  // Merge all sessions
  const allSessions = [...memberSessions, ...adminSessions, ...guestSessions];
  // Count totals for each type
  const totalMember = queryMember
    ? await MyGlobal.prisma.discussion_board_member_sessions.count({
        where: buildMemberWhere(),
      })
    : 0;
  const totalAdmin = queryAdmin
    ? await MyGlobal.prisma.discussion_board_admin_sessions.count({
        where: buildAdminWhere(),
      })
    : 0;
  const totalGuest = queryGuest
    ? await MyGlobal.prisma.discussion_board_guest_sessions.count({
        where: buildGuestWhere(),
      })
    : 0;
  const total = totalMember + totalAdmin + totalGuest;
  // Transform sessions to ISummary
  const data = await Promise.all(
    allSessions.map(async (session) => {
      if ("member" in session) {
        return {
          id: session.id,
          type: "member" as const,
          ip: session.ip,
          href: session.href,
          referrer: session.referrer ?? null,
          user: typia.assert<IDiscussionBoardGuestSession.ISummary["user"]>(
            await DiscussionBoardMemberAtSummaryTransformer.transform(
              session.member,
            ),
          ),
          created_at: toISOStringSafe(session.created_at),
          expired_at: toISOStringSafe(session.expired_at),
        } satisfies IDiscussionBoardGuestSession.ISummary;
      } else if ("discussionBoardAdmin" in session) {
        return {
          id: session.id,
          type: "admin" as const,
          ip: session.ip,
          href: session.href,
          referrer: session.referrer ?? null,
          user: typia.assert<IDiscussionBoardGuestSession.ISummary["user"]>(
            await DiscussionBoardAdminAtSummaryTransformer.transform(
              session.discussionBoardAdmin,
            ),
          ),
          created_at: toISOStringSafe(session.created_at),
          expired_at: toISOStringSafe(session.expired_at),
        } satisfies IDiscussionBoardGuestSession.ISummary;
      } else {
        return {
          id: session.id,
          type: "guest" as const,
          ip: session.ip,
          href: session.href,
          referrer: session.referrer ?? null,
          user: typia.assert<IDiscussionBoardGuestSession.ISummary["user"]>(
            await DiscussionBoardGuestAtSummaryTransformer.transform(
              session.guest,
            ),
          ),
          created_at: toISOStringSafe(session.created_at),
          expired_at: toISOStringSafe(session.expired_at),
        } satisfies IDiscussionBoardGuestSession.ISummary;
      }
    }),
  );
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data,
  };
}

import { IDiscussionBoardActivityReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityReport";
import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIDiscussionBoardActivityReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityReport";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchDiscussionBoardAdminReportsActivity(props: {
  admin: AdminPayload;
  body: IDiscussionBoardActivityReport.IRequest;
}): Promise<IPageIDiscussionBoardActivityReport.ISummary> {
  const page = props.body.page;
  const pageSize = props.body.pageSize ?? 100;
  const limit = props.body.limit ?? 100;
  const effectiveLimit = Math.min(limit, 100);
  const skip = (page - 1) * effectiveLimit;
  const whereInput: Prisma.discussion_board_audit_logsWhereInput = {};
  // Build created_at filter directly without spreading
  const created_at: any = {};
  if (props.body.startDate) {
    created_at.gte = new Date(props.body.startDate);
  }
  if (props.body.endDate) {
    created_at.lte = new Date(props.body.endDate);
  }
  if (Object.keys(created_at).length > 0) {
    whereInput.created_at = created_at;
  }
  if (props.body.actionTypes && props.body.actionTypes.length > 0) {
    whereInput.action_type = { in: props.body.actionTypes };
  }
  if (props.body.actorTypes && props.body.actorTypes.length > 0) {
    whereInput.actor_type = { in: props.body.actorTypes };
  }
  const total = await MyGlobal.prisma.discussion_board_audit_logs.count({
    where: whereInput,
  });
  const actionTypeCounts =
    await MyGlobal.prisma.discussion_board_audit_logs.groupBy({
      by: ["action_type"],
      where: whereInput,
      _count: { action_type: true },
    });
  const actionTypeBreakdown: Record<string, number> = {};
  for (const item of actionTypeCounts) {
    actionTypeBreakdown[item.action_type] = item._count.action_type;
  }
  const actorTypeCounts =
    await MyGlobal.prisma.discussion_board_audit_logs.groupBy({
      by: ["actor_type"],
      where: whereInput,
      _count: { actor_type: true },
    });
  let memberActivityCount = 0;
  let adminActivityCount = 0;
  for (const item of actorTypeCounts) {
    if (item.actor_type === "member") {
      memberActivityCount = item._count.actor_type;
    } else if (item.actor_type === "admin") {
      adminActivityCount = item._count.actor_type;
    }
  }
  const orderByInput: Prisma.discussion_board_audit_logsOrderByWithRelationInput =
    {
      created_at: "desc",
    };
  const records = await MyGlobal.prisma.discussion_board_audit_logs.findMany({
    where: whereInput,
    skip,
    take: effectiveLimit,
    orderBy: orderByInput,
    include: {
      member: {
        select: {
          id: true,
          display_name: true,
          bio: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          _count: {
            select: {
              articles: true,
              comments: true,
            },
          },
        },
      },
      admin: {
        select: {
          id: true,
          email: true,
          display_name: true,
          grade: true,
          created_at: true,
        },
      },
    },
  });
  const actorCounts = await MyGlobal.prisma.$queryRaw<
    Array<{
      actor_id: string;
      actor_type: string;
      _count: {
        id: number;
      };
    }>
  >(Prisma.sql`
      SELECT 
        CASE WHEN member_id IS NOT NULL THEN member_id ELSE admin_id END as actor_id,
        actor_type,
        COUNT(*) as _count
      FROM discussion_board_audit_logs
      WHERE 1=1
        ${
          props.body.startDate
            ? Prisma.sql`AND created_at >= ${new Date(props.body.startDate)}`
            : Prisma.sql``
        }
        ${
          props.body.endDate
            ? Prisma.sql`AND created_at <= ${new Date(props.body.endDate)}`
            : Prisma.sql``
        }
        ${
          props.body.actionTypes && props.body.actionTypes.length > 0
            ? Prisma.sql`AND action_type IN (${Prisma.join(props.body.actionTypes)})`
            : Prisma.sql``
        }
        ${
          props.body.actorTypes && props.body.actorTypes.length > 0
            ? Prisma.sql`AND actor_type IN (${Prisma.join(props.body.actorTypes)})`
            : Prisma.sql``
        }
      GROUP BY 
        CASE WHEN member_id IS NOT NULL THEN member_id ELSE admin_id END,
        actor_type
      ORDER BY _count DESC
      LIMIT 10
    `);
  const topActors: Array<
    IDiscussionBoardMember.ISummary | IDiscussionBoardAdmin.ISummary
  > = [];
  for (const item of actorCounts) {
    if (item.actor_type === "member") {
      const member = await MyGlobal.prisma.discussion_board_members.findUnique({
        where: { id: item.actor_id },
        select: {
          id: true,
          display_name: true,
          bio: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          _count: {
            select: {
              articles: true,
              comments: true,
            },
          },
        },
      });
      if (member) {
        topActors.push({
          id: member.id,
          displayName: member.display_name,
          bio: member.bio,
          articleCount: member._count.articles,
          commentCount: member._count.comments,
          createdAt: toISOStringSafe(member.created_at),
          updatedAt: toISOStringSafe(member.updated_at),
          deletedAt: member.deleted_at
            ? toISOStringSafe(member.deleted_at)
            : null,
        } satisfies IDiscussionBoardMember.ISummary);
      }
    } else if (item.actor_type === "admin") {
      const admin = await MyGlobal.prisma.discussion_board_admins.findUnique({
        where: { id: item.actor_id },
        select: {
          id: true,
          email: true,
          display_name: true,
          grade: true,
          created_at: true,
        },
      });
      if (admin) {
        topActors.push({
          id: admin.id,
          email: admin.email,
          display_name: admin.display_name,
          grade: admin.grade,
          created_at: toISOStringSafe(admin.created_at),
        } satisfies IDiscussionBoardAdmin.ISummary);
      }
    }
  }
  const startDateStr = props.body.startDate
    ? props.body.startDate
    : toISOStringSafe(new Date(0));
  const endDateStr = props.body.endDate
    ? props.body.endDate
    : toISOStringSafe(new Date());
  const reports: IDiscussionBoardActivityReport.ISummary[] = records.map(
    (record, index) => {
      const cursorData = {
        id: record.id,
        created_at: toISOStringSafe(record.created_at),
        page: page,
        index: index,
      };
      return {
        id: v4() as unknown as string & tags.Format<"uuid">,
        start_date: startDateStr,
        end_date: endDateStr,
        total_count: total,
        member_activity_count: memberActivityCount,
        admin_activity_count: adminActivityCount,
        action_type_breakdown: actionTypeBreakdown,
        top_actors: topActors.length > 0 ? topActors : undefined,
        cursor: btoa(JSON.stringify(cursorData)),
        created_at: toISOStringSafe(new Date()),
      } satisfies IDiscussionBoardActivityReport.ISummary;
    },
  );
  const pages = total === 0 ? 0 : Math.ceil(total / effectiveLimit);
  return {
    pagination: {
      current: page,
      limit: effectiveLimit,
      records: total,
      pages: pages,
    } satisfies IPage.IPagination,
    data: reports,
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
